const mysql = require('mysql2/promise');
const fs = require('fs');
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });

class DatabaseService {
  constructor() {
    this.pool = null;
    // internal flag to track connection state without colliding with isConnected() method
    this._connected = false;
  }

  async connect() {
    try {
      // Allow .env to override defaults; match WAMP defaults
      const DB_HOST = process.env.DB_HOST || '127.0.0.1';
      const DB_PORT = Number(process.env.DB_PORT || 3306);
      const DB_USER = process.env.DB_USER || 'root';
      const DB_PASS = process.env.DB_PASS || '';
      const DB_NAME = process.env.DB_NAME || 'serina_evolution';

      // First attempt to connect to the target DB; if fails because DB missing, create it
      this.pool = mysql.createPool({
        host: DB_HOST,
        port: DB_PORT,
        user: DB_USER,
        password: DB_PASS,
        database: DB_NAME,
        waitForConnections: true,
        connectionLimit: 10,
        queueLimit: 0,
        // mysql2 pool does not support some of the older options; keep minimal
      });

      // Test connection
      const connection = await this.pool.getConnection();
      console.log('✅ Connected to MySQL database');
      connection.release();
      this._connected = true;
      
      return true;
    } catch (error) {
      console.error('❌ Database connection failed:', error.message);
      // Try to create database if missing
      if (/unknown database|Base '.*' inconnue/i.test(error.message)) {
        try {
          const DB_HOST = process.env.DB_HOST || '127.0.0.1';
          const DB_PORT = Number(process.env.DB_PORT || 3306);
          const DB_USER = process.env.DB_USER || 'root';
          const DB_PASS = process.env.DB_PASS || '';
          const DB_NAME = process.env.DB_NAME || 'serina_evolution';

          const admin = await mysql.createConnection({
            host: DB_HOST,
            port: DB_PORT,
            user: DB_USER,
            password: DB_PASS
          });
          await admin.query(`CREATE DATABASE IF NOT EXISTS \`${DB_NAME}\` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
          await admin.end();
          console.log(`🆕 Created database ${DB_NAME}`);

          // Try connecting again
          this.pool = mysql.createPool({
            host: DB_HOST,
            port: DB_PORT,
            user: DB_USER,
            password: DB_PASS,
            database: DB_NAME,
            waitForConnections: true,
            connectionLimit: 10,
            queueLimit: 0
          });
          const connection = await this.pool.getConnection();
          console.log('✅ Connected to MySQL database');
          connection.release();
          this._connected = true;

          // Create schema if missing
          await this.ensureSchema();
          return true;
        } catch (e) {
          console.error('❌ Failed to create database/schema:', e.message);
          this._connected = false;
          return false;
        }
      } else {
        this._connected = false;
        return false;
      }
    }
  }

  async disconnect() {
    if (this.pool) {
      await this.pool.end();
      this._connected = false;
      console.log('🔌 Database disconnected');
    }
  }

  async query(sql, params = []) {
    if (!this._connected) {
      throw new Error('Database not connected');
    }

    try {
      const [rows] = await this.pool.execute(sql, params);
      return rows;
    } catch (error) {
      console.error('Database query error:', error);
      throw error;
    }
  }

  // Convenience wrappers and status
  async initialize() {
    const connected = await this.connect();
    if (connected) {
      try { await this.ensureSchema(); } catch (e) { console.warn('⚠️ Schema ensure warning:', e.message); }
    }
    return connected;
  }

  isConnected() {
    return this._connected;
  }

  async close() {
    return this.disconnect();
  }

  async ensureSchema() {
    // Minimal schema to get the app running; expand as needed
    const ddl = [
      `CREATE TABLE IF NOT EXISTS simulations (
        id INT AUTO_INCREMENT PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        config JSON NULL,
        generation INT DEFAULT 0,
        population_count INT DEFAULT 0,
        species_count INT DEFAULT 0,
        status VARCHAR(32) DEFAULT 'created',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS species (
        id INT AUTO_INCREMENT PRIMARY KEY,
        simulation_id INT NOT NULL,
        name VARCHAR(255) NOT NULL,
        population_count INT DEFAULT 0,
        generation_span INT DEFAULT 0,
        extinction_risk FLOAT DEFAULT 0,
        ecological_niche VARCHAR(128) DEFAULT 'generalist',
        traits JSON NULL,
        fitness_average FLOAT DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
        INDEX (simulation_id),
        CONSTRAINT fk_species_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS individuals (
        id INT AUTO_INCREMENT PRIMARY KEY,
        species_id INT NOT NULL,
        name VARCHAR(255) NULL,
        age INT DEFAULT 0,
        energy FLOAT DEFAULT 0,
        position_x FLOAT DEFAULT 0,
        position_y FLOAT DEFAULT 0,
        generation INT DEFAULT 0,
        traits JSON NULL,
        genome JSON NULL,
        phenotype JSON NULL,
        is_alive TINYINT(1) DEFAULT 1,
        birth_time DATETIME NULL,
        death_time DATETIME NULL,
        cause_of_death VARCHAR(255) NULL,
        parent1_id INT NULL,
        parent2_id INT NULL,
        fitness_score FLOAT DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
        INDEX (species_id),
        CONSTRAINT fk_individuals_species FOREIGN KEY (species_id) REFERENCES species(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS evolution_history (
        id INT AUTO_INCREMENT PRIMARY KEY,
        simulation_id INT NOT NULL,
        generation INT NOT NULL,
        population_count INT DEFAULT 0,
        species_count INT DEFAULT 0,
        average_fitness FLOAT DEFAULT 0,
        genetic_diversity FLOAT DEFAULT 0,
        mutations_count INT DEFAULT 0,
        reproductions_count INT DEFAULT 0,
        environment_data JSON NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        INDEX (simulation_id),
        CONSTRAINT fk_eh_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS performance_logs (
        id INT AUTO_INCREMENT PRIMARY KEY,
        simulation_id INT NOT NULL,
        cpu_usage FLOAT DEFAULT 0,
        memory_usage FLOAT DEFAULT 0,
        fps FLOAT DEFAULT 0,
        generations_per_second FLOAT DEFAULT 0,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        INDEX (simulation_id),
        CONSTRAINT fk_pl_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS environment (
        id INT AUTO_INCREMENT PRIMARY KEY,
        simulation_id INT NOT NULL,
        temperature FLOAT DEFAULT 20,
        humidity FLOAT DEFAULT 0.6,
        oxygen_level FLOAT DEFAULT 0.21,
        radiation_level FLOAT DEFAULT 0.0,
        food_availability FLOAT DEFAULT 0.7,
        water_availability FLOAT DEFAULT 0.8,
        predator_pressure FLOAT DEFAULT 0.3,
        competition_level FLOAT DEFAULT 0.5,
        seasonal_factor FLOAT DEFAULT 1.0,
        disaster_probability FLOAT DEFAULT 0.01,
        width INT DEFAULT 1920,
        height INT DEFAULT 1080,
        food_sources JSON NULL,
        water_sources JSON NULL,
        shelter_areas JSON NULL,
        danger_zones JSON NULL,
        change_history JSON NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
        UNIQUE KEY uq_env_sim (simulation_id),
        CONSTRAINT fk_env_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS evolution_events (
        id INT AUTO_INCREMENT PRIMARY KEY,
        simulation_id INT NOT NULL,
        species_id INT NULL,
        event_type VARCHAR(64) NOT NULL,
        event_data JSON NULL,
        generation INT DEFAULT 0,
        recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        INDEX (simulation_id),
        INDEX (species_id),
        CONSTRAINT fk_ev_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE,
        CONSTRAINT fk_ev_species FOREIGN KEY (species_id) REFERENCES species(id) ON DELETE SET NULL
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`,
      `CREATE TABLE IF NOT EXISTS species_traits_history (
        id INT AUTO_INCREMENT PRIMARY KEY,
        species_id INT NOT NULL,
        simulation_id INT NOT NULL,
        generation INT NOT NULL,
        population_count INT DEFAULT 0,
        avg_size FLOAT DEFAULT 0,
        avg_speed FLOAT DEFAULT 0,
        avg_intelligence FLOAT DEFAULT 0,
        avg_endurance FLOAT DEFAULT 0,
        avg_aggression FLOAT DEFAULT 0,
        avg_sociability FLOAT DEFAULT 0,
        avg_fertility FLOAT DEFAULT 0,
        avg_longevity FLOAT DEFAULT 0,
        avg_adaptation FLOAT DEFAULT 0,
        avg_resistance FLOAT DEFAULT 0,
        fitness_average FLOAT DEFAULT 0,
        genetic_diversity FLOAT DEFAULT 0,
        mutation_rate FLOAT DEFAULT 0,
        extinction_risk FLOAT DEFAULT 0,
        traits_data JSON NULL,
        environmental_pressures JSON NULL,
        recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        INDEX (species_id, generation),
        INDEX (simulation_id, generation),
        INDEX (generation),
        CONSTRAINT fk_sth_species FOREIGN KEY (species_id) REFERENCES species(id) ON DELETE CASCADE,
        CONSTRAINT fk_sth_sim FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;`
    ];

    for (const stmt of ddl) {
      await this.query(stmt);
    }
    // Ensure there’s at least one simulation row for id=1
    const sims = await this.query('SELECT id FROM simulations WHERE id = 1');
    if (sims.length === 0) {
      await this.query("INSERT INTO simulations (id, name, status) VALUES (1, 'Default Simulation', 'created')");
    }
    const env = await this.query('SELECT id FROM environment WHERE simulation_id = 1');
    if (env.length === 0) {
      await this.query('INSERT INTO environment (simulation_id) VALUES (1)');
    }
  }

  // Simulation Management
  async createSimulation(config) {
    const sql = `
      INSERT INTO simulations (name, config, status, created_at, updated_at)
      VALUES (?, ?, 'created', NOW(), NOW())
    `;
    const result = await this.query(sql, [
      config.name || 'Unnamed Simulation',
      JSON.stringify(config)
    ]);
    return result.insertId;
  }

  async updateSimulation(id, data) {
    // Map possible aliases to DB columns
    const columnMap = {
      generation: 'generation',
      current_generation: 'generation',
      population_count: 'population_count',
      populationCount: 'population_count',
      species_count: 'species_count',
      status: 'status',
      last_update: 'updated_at',
      updated_at: 'updated_at',
      config: 'config',
      name: 'name'
    };

    const sets = [];
    const values = [];
    for (const [key, value] of Object.entries(data || {})) {
      const column = columnMap[key];
      if (!column) continue;
      sets.push(`${column} = ?`);
      // JSON stringify config if object
      if (column === 'config' && typeof value === 'object') {
        values.push(JSON.stringify(value));
      } else {
        values.push(value);
      }
    }

    if (sets.length === 0) {
      return { affectedRows: 0 };
    }

    const sql = `UPDATE simulations SET ${sets.join(', ')}, updated_at = NOW() WHERE id = ?`;
    values.push(id);
    return await this.query(sql, values);
  }

  async getSimulation(id) {
    const sql = 'SELECT * FROM simulations WHERE id = ?';
    const results = await this.query(sql, [id]);
    return results[0];
  }

  async getAllSimulations() {
    const sql = 'SELECT * FROM simulations ORDER BY created_at DESC';
    return await this.query(sql);
  }

  // Species Management
  async createSpecies(simulationId, name, traits = {}, options = {}) {
    const sql = `
      INSERT INTO species (simulation_id, name, population_count, generation_span, 
                           extinction_risk, ecological_niche, traits, fitness_average, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())
    `;
    const res = await this.query(sql, [
      simulationId,
      name,
      options.population_count ?? 0,
      options.generation_span ?? 0,
      options.extinction_risk ?? 0,
      options.ecological_niche ?? 'generalist',
      JSON.stringify(traits),
      options.fitness_average ?? 0
    ]);
    return res.insertId;
  }
  async saveSpecies(simulationId, species) {
    const sql = `
      INSERT INTO species (simulation_id, name, population_count, generation_span, 
                          extinction_risk, ecological_niche, traits, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), NOW())
      ON DUPLICATE KEY UPDATE
        population_count = VALUES(population_count),
        generation_span = VALUES(generation_span),
        extinction_risk = VALUES(extinction_risk),
        traits = VALUES(traits),
        updated_at = NOW()
    `;
    
    return await this.query(sql, [
      simulationId,
      species.name,
      species.populationCount,
      species.generationSpan,
      species.extinctionRisk,
      species.ecologicalNiche,
      JSON.stringify(species.averageTrait)
    ]);
  }

  async getSpeciesBySimulation(simulationId) {
    const sql = 'SELECT * FROM species WHERE simulation_id = ? ORDER BY population_count DESC';
    const results = await this.query(sql, [simulationId]);
    
    return results.map(row => ({
      ...row,
      traits: typeof row.traits === 'string' ? JSON.parse(row.traits || '{}') : (row.traits || {})
    }));
  }

  // Alias used by some routes
  async getSpecies(simulationId) {
    return this.getSpeciesBySimulation(simulationId);
  }

  async getSpeciesById(speciesId) {
    const sql = 'SELECT * FROM species WHERE id = ? LIMIT 1';
    const results = await this.query(sql, [speciesId]);
    if (!results[0]) return null;
    return {
      ...results[0],
      traits: typeof results[0].traits === 'string' ? JSON.parse(results[0].traits || '{}') : (results[0].traits || {})
    };
  }

  // Species Traits History Management
  async saveSpeciesTraitsHistory(speciesId, simulationId, generation, traitsData) {
    const sql = `
      INSERT INTO species_traits_history (
        species_id, simulation_id, generation, population_count,
        avg_size, avg_speed, avg_intelligence, avg_endurance, avg_aggression,
        avg_sociability, avg_fertility, avg_longevity, avg_adaptation, avg_resistance,
        fitness_average, genetic_diversity, mutation_rate, extinction_risk,
        traits_data, environmental_pressures, recorded_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
    `;
    
    const traits = traitsData.avgTraits || {};
    return await this.query(sql, [
      speciesId,
      simulationId,
      generation,
      traitsData.populationCount || 0,
      traits.size || 0,
      traits.speed || 0,
      traits.intelligence || 0,
      traits.endurance || 0,
      traits.aggression || 0,
      traits.sociability || 0,
      traits.fertility || 0,
      traits.longevity || 0,
      traits.adaptation || 0,
      traits.resistance || 0,
      traitsData.fitnessAverage || 0,
      traitsData.geneticDiversity || 0,
      traitsData.mutationRate || 0,
      traitsData.extinctionRisk || 0,
      JSON.stringify(traitsData),
      JSON.stringify(traitsData.environmentalPressures || {})
    ]);
  }

  async getSpeciesTraitsHistory(speciesId, generations = null) {
    let sql = 'SELECT * FROM species_traits_history WHERE species_id = ?';
    const params = [speciesId];
    
    if (generations) {
      sql += ' AND generation >= ? ORDER BY generation ASC LIMIT ?';
      params.push(Math.max(0, generations.from || 0), generations.limit || 100);
    } else {
      sql += ' ORDER BY generation DESC LIMIT 50';
    }
    
    const results = await this.query(sql, params);
    return results.map(row => ({
      ...row,
      traits_data: typeof row.traits_data === 'string' ? JSON.parse(row.traits_data || '{}') : row.traits_data,
      environmental_pressures: typeof row.environmental_pressures === 'string' ? JSON.parse(row.environmental_pressures || '{}') : row.environmental_pressures
    }));
  }

  async getTraitsEvolutionTrends(speciesId, traitName, generations = 50) {
    const sql = `
      SELECT generation, 
             CASE 
               WHEN ? = 'size' THEN avg_size
               WHEN ? = 'speed' THEN avg_speed
               WHEN ? = 'intelligence' THEN avg_intelligence
               WHEN ? = 'endurance' THEN avg_endurance
               WHEN ? = 'aggression' THEN avg_aggression
               WHEN ? = 'sociability' THEN avg_sociability
               WHEN ? = 'fertility' THEN avg_fertility
               WHEN ? = 'longevity' THEN avg_longevity
               WHEN ? = 'adaptation' THEN avg_adaptation
               WHEN ? = 'resistance' THEN avg_resistance
               ELSE 0
             END as trait_value,
             fitness_average,
             recorded_at
      FROM species_traits_history 
      WHERE species_id = ? 
      ORDER BY generation DESC 
      LIMIT ?
    `;
    
    return await this.query(sql, [
      traitName, traitName, traitName, traitName, traitName,
      traitName, traitName, traitName, traitName, traitName,
      speciesId, generations
    ]);
  }

  async getSpeciesTraitsComparison(simulationId, generation) {
    const sql = `
      SELECT species_id, 
             avg_size, avg_speed, avg_intelligence, avg_endurance, avg_aggression,
             avg_sociability, avg_fertility, avg_longevity, avg_adaptation, avg_resistance,
             fitness_average, population_count
      FROM species_traits_history 
      WHERE simulation_id = ? AND generation = ?
      ORDER BY fitness_average DESC
    `;
    
    return await this.query(sql, [simulationId, generation]);
  }

  // Individual Management
  async saveIndividual(individual) {
    const sql = `
      INSERT INTO individuals (species_id, name, age, energy, position_x, position_y,
                              generation, genome, phenotype, is_alive, birth_time, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
    `;
    
    return await this.query(sql, [
      individual.speciesId,
      individual.name,
      individual.age,
      individual.energy,
      individual.position.x,
      individual.position.y,
      individual.generation,
      JSON.stringify(individual.genome),
      JSON.stringify(individual.phenotype),
      individual.isAlive,
      individual.birthTime
    ]);
  }

  // Flexible update: only updates provided fields
  async updateIndividual(id, data = {}) {
    const columnMap = {
      age: 'age',
      energy: 'energy',
      position_x: 'position_x',
      position_y: 'position_y',
      'position.x': 'position_x',
      'position.y': 'position_y',
      is_alive: 'is_alive',
      isAlive: 'is_alive',
      death_time: 'death_time',
      cause_of_death: 'cause_of_death',
      traits: 'traits',
      generation: 'generation',
      fitness_score: 'fitness_score'
    };

    const sets = [];
    const values = [];

    for (const [key, value] of Object.entries(data)) {
      const column = columnMap[key];
      if (!column) continue;
      sets.push(`${column} = ?`);
      if (column === 'traits' && typeof value === 'object') {
        values.push(JSON.stringify(value));
      } else if (key === 'position.x' || key === 'position.y') {
        values.push(value);
      } else {
        values.push(value);
      }
    }

    // Support nested position
    if (data.position && typeof data.position === 'object') {
      if (data.position.x !== undefined) {
        sets.push('position_x = ?');
        values.push(data.position.x);
      }
      if (data.position.y !== undefined) {
        sets.push('position_y = ?');
        values.push(data.position.y);
      }
    }

    if (sets.length === 0) return { affectedRows: 0 };

    const sql = `UPDATE individuals SET ${sets.join(', ')}, updated_at = NOW() WHERE id = ?`;
    values.push(id);
    return await this.query(sql, values);
  }

  // Create individual (API expected by evolution engine)
  async createIndividual(individual) {
    const sql = `
      INSERT INTO individuals (species_id, name, energy, position_x, position_y, generation, 
                               parent1_id, parent2_id, is_alive, traits, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
    `;
    return await this.query(sql, [
      individual.species_id,
      individual.name,
      individual.energy ?? 0,
      individual.position_x ?? 0,
      individual.position_y ?? 0,
      individual.generation ?? 0,
      individual.parent1_id || null,
      individual.parent2_id || null,
      individual.is_alive !== undefined ? individual.is_alive : true,
      JSON.stringify(individual.traits || {})
    ]);
  }

  async getIndividuals(speciesId, limit = 100) {
    const sql = `
      SELECT * FROM individuals WHERE species_id = ? ORDER BY created_at DESC LIMIT ?
    `;
    return await this.query(sql, [speciesId, limit]);
  }

  // Evolution History
  async saveEvolutionSnapshot(simulationId, generation, data) {
    const sql = `
      INSERT INTO evolution_history (simulation_id, generation, population_count,
                                   species_count, average_fitness, genetic_diversity,
                                   mutations_count, reproductions_count, environment_data, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
    `;
    
    return await this.query(sql, [
      simulationId,
      generation,
      data.populationCount,
      data.speciesCount,
      data.averageFitness,
      data.geneticDiversity,
      data.mutationsCount,
      data.reproductionsCount,
      JSON.stringify(data.environment)
    ]);
  }

  async getEvolutionHistory(simulationId, limit = 100) {
    const sql = `
      SELECT * FROM evolution_history 
      WHERE simulation_id = ? 
      ORDER BY generation DESC 
      LIMIT ?
    `;
    
    const results = await this.query(sql, [simulationId, limit]);
    return results.map(row => ({
      ...row,
      environment_data: typeof row.environment_data === 'string' ? JSON.parse(row.environment_data || '{}') : (row.environment_data || {})
    }));
  }

  // Analytics and Statistics
  async getSimulationStats(simulationId) {
    const sql = `
      SELECT 
        s.name, s.generation, s.population_count, s.status,
        COUNT(sp.id) as species_count,
        COUNT(i.id) as total_individuals,
        AVG(i.energy) as avg_energy,
        MAX(eh.generation) as max_generation
      FROM simulations s
      LEFT JOIN species sp ON s.id = sp.simulation_id
      LEFT JOIN individuals i ON sp.id = i.species_id AND i.is_alive = 1
      LEFT JOIN evolution_history eh ON s.id = eh.simulation_id
      WHERE s.id = ?
      GROUP BY s.id
    `;
    
    const results = await this.query(sql, [simulationId]);
    return results[0];
  }

  async getPopulationTrends(simulationId, generations = 50) {
    const sql = `
      SELECT generation, population_count, species_count, average_fitness, genetic_diversity
      FROM evolution_history
      WHERE simulation_id = ?
      ORDER BY generation DESC
      LIMIT ?
    `;
    
    return await this.query(sql, [simulationId, generations]);
  }

  // Real-time Performance Monitoring
  async logPerformanceMetrics(simulationId, metrics) {
    const sql = `
      INSERT INTO performance_logs (simulation_id, cpu_usage, memory_usage, 
                                  fps, generations_per_second, timestamp)
      VALUES (?, ?, ?, ?, ?, NOW())
    `;
    
    return await this.query(sql, [
      simulationId,
      metrics.cpuUsage,
      metrics.memoryUsage,
      metrics.frameRate,
      metrics.generationsPerSecond
    ]);
  }

  async getRecentPerformanceMetrics(simulationId, minutes = 5) {
    const sql = `
      SELECT * FROM performance_logs
      WHERE simulation_id = ? AND timestamp >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
      ORDER BY timestamp DESC
    `;
    
    return await this.query(sql, [simulationId, minutes]);
  }

  // Cleanup and Maintenance
  async cleanupOldData(daysOld = 30) {
    const sqls = [
      'DELETE FROM performance_logs WHERE timestamp < DATE_SUB(NOW(), INTERVAL ? DAY)',
      'DELETE FROM evolution_history WHERE created_at < DATE_SUB(NOW(), INTERVAL ? DAY)',
      'DELETE FROM individuals WHERE death_time IS NOT NULL AND death_time < DATE_SUB(NOW(), INTERVAL ? DAY)'
    ];
    
    let deletedRows = 0;
    for (const sql of sqls) {
      const result = await this.query(sql, [daysOld]);
      deletedRows += result.affectedRows || 0;
    }
    
    console.log(`🧹 Cleaned up ${deletedRows} old records`);
    return deletedRows;
  }

  // Environment Management
  async getEnvironmentBySimulation(simulationId) {
    const sql = 'SELECT * FROM environment WHERE simulation_id = ? LIMIT 1';
    const results = await this.query(sql, [simulationId]);
    return results[0] || null;
  }

  async updateEnvironment(simulationId, envData) {
    // Try update first
    const fields = { ...envData };
    delete fields.id;
    delete fields.simulation_id;

    const sets = [];
    const values = [];
    for (const [key, value] of Object.entries(fields)) {
      sets.push(`${key} = ?`);
      if (['food_sources','water_sources','shelter_areas','danger_zones','change_history'].includes(key) && typeof value === 'object') {
        values.push(JSON.stringify(value));
      } else {
        values.push(value);
      }
    }
    if (sets.length === 0) return { affectedRows: 0 };

    const updateSql = `UPDATE environment SET ${sets.join(', ')}, updated_at = NOW() WHERE simulation_id = ?`;
    const result = await this.query(updateSql, [...values, simulationId]);

    // If no row updated, insert
    if (result.affectedRows === 0) {
      const columns = ['simulation_id', ...Object.keys(fields), 'created_at', 'updated_at'];
      const placeholders = columns.map(() => '?').join(', ');
      const insertSql = `INSERT INTO environment (${columns.join(', ')}) VALUES (${placeholders})`;
      const insertValues = [simulationId, ...Object.keys(fields).map(k => {
        const v = fields[k];
        if (['food_sources','water_sources','shelter_areas','danger_zones','change_history'].includes(k) && typeof v === 'object') {
          return JSON.stringify(v);
        }
        return v;
      }), new Date(), new Date()];
      return await this.query(insertSql, insertValues);
    }

    return result;
  }

  // Population helpers (used by evolution engine)
  async getPopulation(simulationId = null) {
    if (simulationId) {
      const sql = `
        SELECT i.* FROM individuals i
        JOIN species s ON i.species_id = s.id
        WHERE i.is_alive = 1 AND s.simulation_id = ?
      `;
      return await this.query(sql, [simulationId]);
    }
    return await this.query('SELECT * FROM individuals WHERE is_alive = 1');
  }

  async clearPopulation(simulationId = null) {
    if (simulationId) {
      const sql = `
        DELETE i FROM individuals i
        JOIN species s ON i.species_id = s.id
        WHERE s.simulation_id = ?
      `;
      return await this.query(sql, [simulationId]);
    }
    return await this.query('DELETE FROM individuals');
  }

  async saveGenerationStats(simulationId, generation, population) {
    const alive = population.filter(p => p.is_alive).length;
    const speciesIds = new Set(population.map(p => p.species_id)).size;
    const avgEnergy = population.length ? (population.reduce((s, p) => s + (p.energy || 0), 0) / population.length) : 0;

    const data = {
      populationCount: alive,
      speciesCount: speciesIds,
      averageFitness: avgEnergy / 100,
      geneticDiversity: 0,
      mutationsCount: 0,
      reproductionsCount: 0,
      environment: {}
    };
    return this.saveEvolutionSnapshot(simulationId, generation, data);
  }

  async getSpeciesStats(simulationId) {
    return this.getSpeciesBySimulation(simulationId);
  }

  async getTotalMutations(simulationId = null) {
    try {
      let sql = 'SELECT COUNT(*) as cnt FROM evolution_events WHERE event_type = \'mutation\'';
      const params = [];
      if (simulationId) { sql += ' AND simulation_id = ?'; params.push(simulationId); }
      const rows = await this.query(sql, params);
      return rows[0]?.cnt || 0;
    } catch (e) {
      return 0;
    }
  }

  async getTotalReproductions(simulationId = null) {
    try {
      let sql = 'SELECT COUNT(*) as cnt FROM evolution_events WHERE event_type = \'reproduction\'';
      const params = [];
      if (simulationId) { sql += ' AND simulation_id = ?'; params.push(simulationId); }
      const rows = await this.query(sql, params);
      return rows[0]?.cnt || 0;
    } catch (e) {
      return 0;
    }
  }
}

module.exports = new DatabaseService();